// Expectedbits are ORIGINAL actualcapture bytes, never generated by the helper.
const fs=require('fs'),ts=require('typescript'),vm=require('vm'),crypto=require('crypto'),path=require('path');
const args=new Map();for(let i=2;i<process.argv.length;i+=2)args.set(process.argv[i],process.argv[i+1]);
const repo=args.get('--repo');if(!repo||!args.get('--capture')||!args.get('--output'))throw Error('Required --repo --capture --output');
const moduleFile=path.join(repo,'apps/web/src/engine/src/presets/sourceArmFmaF32.ts'),m={exports:{}};vm.runInNewContext(ts.transpileModule(fs.readFileSync(moduleFile,'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2020}}).outputText,m);
const b=fs.readFileSync(args.get('--capture'));if(crypto.createHash('sha256').update(b).digest('hex')!=='cdfe52191e0e104297f13337adedc6fbab742149004ec1f18e30ad77047a2862')throw Error('capture changed');const rows=[];let checked=0,wrong=0;for(let i=64,index=0;i<b.length;i+=16,index++){const input=b.readUInt32LE(i),estimate=b.readUInt32LE(i+4),expected=b.readUInt32LE(i+8);if(input>0&&input<0x7f800000&&estimate<0x7f800000){const a=(input^0x80000000)>>>0,value=m.exports.arm64FusedMultiplyAddF32Bits(a,estimate,0x40000000);checked++;if(value!==expected)wrong++;if(index%137===0||input<0x01000000)rows.push([a,estimate,expected,index]);}}
